\Chapter{BOOK I}{Properties of the Plane}

\Paragraph{64.}{Relations of Points, Lines, and Planes.} If a line or a plane
contains a point, the point is said to be \emph{on} the line or \emph{in} the
plane and the line or plane is said to pass \emph{through} the point.
If a plane contains a line, the line is said to be \emph{in} the plane
and the plane is said to pass \emph{through} the line.

\index{Axioms@\textbf{Axioms}|(}
\begin{Axiom}{65.}{1.}
If two points of a straight line lie in a plane
then the whole line lies in the plane.
\end{Axiom}

\begin{Remark}
Since a line is endless, it follows from this axiom that a plane is
endless in all its directions.
\end{Remark}

\begin{Axiom}{66.}{2.}
Through three non-collinear points one and
only one plane can be passed.
\end{Axiom}

\begin{Axiom}{67.}{3.}
Two distinct planes cannot \\
meet in one point only.\hfill\smash[t]{\raisebox{-0.125in}{\Input{017a}{1.25in}}}
\end{Axiom}
\index{Axioms@\textbf{Axioms}|)}


\Paragraph{68.}{Determination of a Plane.} A plane is said to be \emph{determined}
by certain elements (lines or points) if this plane contains
these elements while no other plane does contain them.
\index{Plane@\textbf{Plane}!determination of}

\begin{wrapfigure}[5]{r}{1.5in}
\vspace*{-0.375in}
\quad\Input{017b}{1.5in}
\end{wrapfigure}
\begin{Remark}
While two points determine a straight line it
is obvious that two points do not determine a plane.
The figure shows three planes, $L$, $M$, $N$, all passing
through the two points $A$~and $B$. But only a certain
one of these planes contains a given point~$C$
which is not in the line~$AB$.

We, therefore, say that three non-collinear points determine a plane,
while any number of collinear points fail to determine a plane.
\end{Remark}


\Section{LINE COMMON TO TWO PLANES}
\SecToc{Perpendicular Planes and Lines}

\begin{Theorem}{69.}{I.}
Two intersecting planes meet in a
straight line.
\end{Theorem}
\begin{center}
\vspace*{-0.25in}
\Input{018a}{0.6\textwidth}
\end{center}
\vspace*{-0.25in}

\Objective{Given two intersecting planes $M$~and $N$.}
{To prove that they meet in a straight line~$AB$.}

\Proof: If two planes intersect they meet in at least two
points, as $A$~and $B$.\hfill Ax.~3, §~\Sref{67}

But $A$~and $B$ determine a line which lies wholly in $M$~and
also wholly in~$N$.\hfill Ax.~1, §~\Sref{65}

Hence the planes have the straight line~$AB$ in common.

A point~$C$ not in~$AB$ cannot lie in both $M$~and $N$, for in that
case the planes would have three non-collinear points in common
and hence would coincide.\hfill Ax.~2, §~\Sref{66}

Hence the planes $M$~and $N$ meet in the straight line~$AB$.
\QED 

\Paragraph{70.}{Foot of a Line Meeting a Plane.} The point in which a
\index{Foot@\textbf{Foot}!of a line}
straight line meets a plane is called the \emph{foot of the line}.

\Paragraph{71.}{Line and Plane Perpendicular to Each Other.} A line is
\index{Foot@\textbf{Foot}!of a perpendicular}
\index{Perpendicular@\textbf{Perpendicular}!line to a plane}
\index{Perpendicular@\textbf{Perpendicular}!plane to a line}
said to be \emph{perpendicular to a plane} if it is perpendicular to
every line in the plane passing through its foot. In this case
the plane is also said to be perpendicular to the line.

\noindent\begin{minipage}[b]{\textwidth-1.25in}
\Indent\Paragraph{72.}{Line and Plane Oblique to Each Other.} A line which meets
a plane and is not perpendicular to it is
said to be \emph{oblique} to the plane. The plane
is also said to be oblique to the line.
\end{minipage}
\hfil\smash{\Input{018b}{1.25in}}\hfil


\begin{Remark}
\noindent In the figure, $PA$ is perpendicular to the plane~$M$
and $QA$ is oblique to it.
\end{Remark}


\Section{ELEMENTS WHICH DETERMINE A PLANE}

\begin{Theorem}{73.}{II.}
A plane is determined by \emph{(1)} a
line and a point not on it, \emph{(2)} two intersecting lines,
and \emph{(3)} two parallel lines.
\end{Theorem}


\begin{center}
\Input{019abc}{\textwidth}
\end{center}

\Objective{Given (1) a line~$l$ and a point~$P$ not on it; (2) two intersecting
lines $l_1$~and $l_2$; (3) two parallel lines $l_1$~and $l_2$.}
{To prove that in each case a plane is determined.}

\noindent\begin{minipage}[b]{\textwidth-1.375in}
\Indent\Proof: (1) Let $A$~and $B$ be two points on~$l$. Then
one and only one plane~$M$ can be passed through $l$~and
$P$ because one and only one plane can be passed
through $A$, $B$, and~$P$.\hfill \textsc{Ax}.~2, §~\Sref{66}


\Indent(2) Let $A$ be the intersection point of $l_1$~and $l_2$, and
$B$~and $C$ any other points, one on~$l_1$ and the other on~$l_2$.
Then $A$, $B$, and~$C$ determine the plane~$N$ in which lie
$l_1$~and $l_2$.\hfill \textsc{Axs}.~2, 1. §§~\Sref{66}, \Sref{65}


\Indent(3) By definition $l_1$~and $l_2$ lie in a plane~$R$. They
lie in only one such plane since the points $A$~and $B$
on~$l_1$ and~$C$ on~$l_2$ lie in only one plane.
\QED
\end{minipage}
\hfill\smash{\Input{019def}{1.25in}}

\begin{Corollary}{74.}{1.}
Through a line there is more than one
plane.
\end{Corollary}

\noindent\begin{minipage}[b]{\textwidth-1.5in}
\Indent\begin{Suggestion}
Let $M$~be a plane through the given
line~$l$, and~$C$ a point not in~$M$. Then $l$~and $C$ determine
a plane~$N$ through~$l$ different from~$M$.
\end{Suggestion}

\Indent\begin{Corollary}{75.}{2.}
At a point on a line
there is more than one perpendicular to the line.
\end{Corollary}
\end{minipage}
\hfill\smash{\Input{019g}{1.5in}}

\begin{Suggestion}
Let $M$~and $N$ be planes each passing through the given
line~$l$. Then in each plane there is a line~$\perp l$ at any point~$A$ on it.
\end{Suggestion}


\Section{LINE PERPENDICULAR TO THE PLANE OF TWO GIVEN LINES}

\begin{Theorem}{76.}{III.}
If a line is perpendicular to
each of two lines at their point of intersection, it is
perpendicular to the plane of these lines.
\end{Theorem}

\begin{center}
\Input{020a}{0.6\textwidth}
\end{center}

\Objective{Given a line~$l$ perpendicular to each of the lines $l_1$~and $l_2$ at
the point~$P$.}
{To prove that~$l$ is perpendicular to the plane of $l_1$~and $l_2$.}

\Proof: Let $M$ be the plane of $l_1$~and $l_2$, and let~$l_3$ be any line
in~$M$ through~$P$. Draw a line meeting $l_1$, $l_2$, and~$l_3$ in the points
$B$, $C$, and~$D$ respectively. Let $E$~and $F$ be points on~$l$, on
opposite sides of~$P$, and such that $EP=FP$. Draw $EB$, $ED$,
$EC$, $FB$, $FD$, $FC$.

Then prove:
\begin{align*}
\text{(1)} \bigtriangleup EBP &= \bigtriangleup FBP; \quad
\text{(2)} \bigtriangleup ECP = \bigtriangleup FCP; \\
\text{(3)} \bigtriangleup EBC &= \bigtriangleup FBC; \quad
\text{(4)} \bigtriangleup EBD = \bigtriangleup FBD; \\
\text{(5)} \bigtriangleup EPD &= \bigtriangleup FPD; \quad
\text{(6)} \,\angle\, EPD = \angle\, FPD. \\
\therefore\ & EP \text{ is perpendicular to~$l_3$.} \tag*{Why?}
\end{align*}

But $l_3$ is any line in~$M$ through~$P$. \\
\noindent\null\hfill$\therefore$\ line $l \perp$ plane $M$.\hfill §~\Sref{71} \\
\QED

\begin{Corollary}{77.}{}
If each of two lines is perpendicular to a
third line at the same point, then the plane of the two lines is
perpendicular to the third line.
\end{Corollary}


