\Section{PLANE PERPENDICULAR TO A LINE}

\begin{Theorem}{78.}{IV.}
Through a point there is one
and only one plane perpendicular to a line.
\end{Theorem}

\vspace*{-0.125in}
\begin{center}
\Input{022ab}{}
\end{center}
\vspace*{-0.25in}

\Objective{Given a line~$l$ and a point~$P$.}
{To prove that through~$P$ there is one and only one plane $\perp l$.}

\Proof: \Case{(1)}{When the point~$P$ is on the line~$l$.}\quad \textsc{Fig}.~1.

Through $P$ draw lines $PQ$~and $PQ'$ both $\perp l$. Then the
plane~$M$, determined by $PQ$~and $PQ'$, is $\perp l$.\hfill §~\Sref{77}

To prove that $M$ is the only plane through~$P$ which is $\perp l$,
suppose that a plane~$M'$ through~$P$ is also $\perp l$. Let $R$ be a
plane through~$l$ meeting $M$~and $M'$ in two lines. Then these
lines would both lie in~$R$ and be $\perp l$, which is impossible.\hfill §~\Sref{29}

\Case{(2)}{When the point~$P$ is not on the line~$l$.}\quad \textsc{Fig}.~2.

Let $PQ$ be a line $\perp l$ and let $N$ be a plane $\perp l$ at~$Q$.

Then the plane~$N$ passes through~$P$ and is the plane
required.

For if $P$ does not lie in~$N$, then a plane~$R'$ determined by $l$~and
$PQ$ cuts~$N$ in a line~$l'$ which is $\perp l$ (§~\Sref{71}), and $PQ$~and $l'$ are
each $\perp l$ at the point~$Q$ in plane~$R'$, which is impossible.\hfill §~\Sref{29}

\noindent\begin{minipage}[b]{\textwidth-1.75in}
\Indent Suppose, now, that there are two planes
through~$P$ each $\perp l$. These planes cannot
meet~$l$ in the same point (Case 1). Let them
meet~$l$ in $Q$~and $Q'$. Then $PQ$~and $PQ'$ are
each $\perp l$, which is impossible.
\QED
\end{minipage}
\hfill\smash{\Input{022c}{1.5in}}

\begin{Corollary}{79.}{}
All lines perpendicular to a line at the same
point lie in the plane perpendicular to the line at this point.
\end{Corollary}


\Section{LINE PERPENDICULAR TO A PLANE}

\begin{Theorem}{80.}{V.}
Through a point there is one and
only one line perpendicular to a plane.
\end{Theorem}

\begin{center}
\vspace*{-0.25in}
\Input{023ab}{}
\end{center}
\vspace*{-0.25in}

\Objective{Given a plane~$M$ and a point~$P$.}
{To prove that through~$P$ there is one and only one line $\perp M$.}

\Proof: \Case{(1)}{When $P$ is in the plane~$M$} (first figure). Let $l_1$~be any line
in~$M$ through~$P$, and let $N$ be a plane $\perp l_1$ at~$P$ and meeting~$M$ in the
line~$l_2$. Let $PA$ be a line in~$N$ and $\perp l_2$. Then $PA$ is also $\perp l_1$.\hfill §~\Sref{71}
\[
\therefore PA \perp M. \tag*{§~\Sref{76}.}
\]

\Case{(2)}{When $P$ is not in the plane~$M$} (second figure). Let~$l$ be any line
in the plane~$M$. Through~$P$ pass a plane~$N' \perp l$ at~$A$ and meeting~$M$ in
the line~$AK$. From~$P$ in plane~$N'$ draw a line~$PO \perp AK$ and extend it
to~$P'$ so that $OP' = PO$. Let $B$ be any point in~$l$ different from~$A$.
Draw $PB$, $PA$, $P'B$, $P'A$, and~$OB$.

Then prove (1)~$\triangle POA = \triangle P'OA$;\quad (2)~$\triangle PAB = \triangle P'AB$;\\
(3)~$\triangle POB = \triangle P'OB$;\quad (4)~$\angle POB = \angle P'OB$;\quad (5)~$PO \perp OB$.
\[
\therefore PO \perp M. \tag*{§~\Sref{76}}
\]

\begin{wrapfigure}[7]{r}{3in}
\vspace*{-0.25in}
\Input{023cd}{3in}
\end{wrapfigure}
If in either case~(1) or case~(2) there were two lines $PA$~and
$PB$ each $\perp M$, then the
plane~$R$ of these lines would
cut~$M$ in a line~$l$. Hence
$PA$~and $PB$ would both
lie in~$R$ and be $\perp l$, which
also lies in~$R$. But this is
impossible by §~\Sref{29}.

Hence $PA$ is the only line through~$P$ which is $\perp M$.
\QED


