\Section{OBLIQUE LINES FROM A POINT TO A PLANE}

\noindent\begin{minipage}[b]{\textwidth-2in}
\Indent\begin{Theorem}{81.}{VI.}
Oblique lines from a point to a
plane meeting the plane at equal distances from the
foot of the perpendicular are equal; and

\Indent conversely, two equal oblique lines from a point to
a plane meet the plane at equal distances from the foot
of the perpendicular.
\end{Theorem}
\end{minipage}
\hfill
\raisebox{0.25in}{\Input{025a}{2in}}

\Objective{(1) Given $PC \perp M$, and $AC = BC$.}{To prove that $PA = PB$.}

\begin{Suggestion}
Suggestion. Prove $\triangle PCA = \triangle PCB$.
\end{Suggestion}

\Objective{(2) Given $PC \perp M$, and $PA = PB$.}{To prove that $AC = BC$.}

\begin{Suggestion}
Suggestion. Prove $\triangle PCA = \triangle PCB$.
\end{Suggestion}

\begin{Corollary}{82.}{}
The perpendicular is the shortest distance
from a point to a plane.
\end{Corollary}

Hence \emph{the distance} from a point to a plane means the perpendicular
distance.

