\Section{PARALLEL LINES PERPENDICULAR TO THE SAME PLANE}

\begin{Theorem}{83.}{VII.} Two lines perpendicular to the
same plane are parallel; and

Conversely, if one of two parallel lines is perpendicular
to a plane, the other is also.
\end{Theorem}

\begin{center}
\Input{027ab}{}
\end{center}

\Objective
{Given (1) $AB$ and $CD$ each $\perp$ the plane $M$.\quad \textsc{Fig}.~1.}
{To prove that $AB \parallel CD$.}

\Proof: Draw $BD$ and make $DE \perp DB$.

Take points $A$ and $E$ so that $BA = DE$, and draw $AD$, $AE$,
and $BE$.

Now prove: (1)~$\triangle ABD = \triangle BDE$ and $\therefore AD = BE$;

(2)~$\triangle ADE = \triangle ABE$ and $\therefore\angle ADE = \angle ABE = \text{Rt.}~\angle$.

$\therefore DC$, $DA$, $DB$, and $BA$ all lie in the same plane.\hfill §~\Sref{79} \\
\null\hfill $AB \parallel CD$.\hfill §~\Sref{34}

\Objective{Given (2) $AB \parallel CD$ and $AB \perp M$.\quad \textsc{Fig}.~2.}
          {To prove that $CD \perp M$.}

\Proof: If $CD$ is not $\perp M$ let $C'D$ be $\perp M$.

Then $C'D \parallel AB$ by case (1), and $C'D$ coincides with $CD$ §~\Sref{21}
and $\therefore CD \perp M$.

\noindent\begin{minipage}[b]{\textwidth-1.5in}
\Indent\begin{Corollary}{84.}{1.}
If each of two lines is
parallel to a third line they are parallel to each
other.
\end{Corollary}

\Indent\begin{Corollary}{85.}{2.}
If a plane is perpendicular
to one of two parallel lines, it is perpendicular
to the other.
\end{Corollary}
\end{minipage}
\hfill\raisebox{0.25in}{\Input{027c}{1.25in}}



\Section{PARALLEL PLANES AND LINES}
\SecToc{Parallel Planes and Lines}

\Paragraph{86.}{Parallel Planes.} Two planes which do not meet are said
to be \emph{parallel}.
\index{Parallel@\textbf{Parallel}!plane to a plane}

\Paragraph{87.}{Line Parallel to a Plane.} A straight line and a plane
which do not meet are said to be parallel.
\index{Parallel@\textbf{Parallel}!line to a plane}

\noindent\begin{minipage}[b]{\textwidth-2in}
\Indent\Paragraph{88.}{Intercepted Segments.} If a
straight line $l_2$ meets two planes in $A$
and $B$, then the segment $AB$ is said
to be \emph{intercepted} by the planes.
\index{Segment@\textbf{Segment}!intercepted by planes}

\Indent\begin{Remark}
Any line, as $l_1$, in either of two parallel
planes, $M$ and $N$, is parallel to the other
plane. The segment $AB$ on the line $l_2$
is intercepted by the planes.
\end{Remark}
\end{minipage}
\hfill\smash[b]{\raisebox{-0.25in}{\Input{028a}{2in}}}


\Section{LINE PARALLEL TO A PLANE}

\begin{Theorem}{89.}{VIII.} If a straight line is parallel
to a given plane, it is parallel to the intersection of
any plane through it with the given plane.
\end{Theorem}

\begin{center}
\Input{028b}{0.6\textwidth}
\end{center}

\begin{Suggestion}[ for proof]
If $l_1$ is the given line, $M$ the given plane, and
$l_2$ the intersection of a plane $N$ through $l_1$ with $M$, show that $l_1$ and $l_2$ lie
in plane $N$ and cannot meet.
\end{Suggestion}

\begin{Corollary}{90.}{1.}
If a line outside a plane is parallel to
some line in the plane, then the first line is parallel to the plane.
\end{Corollary}

\noindent\begin{minipage}[b]{\textwidth-1.5in}
\Indent\begin{Corollary}{91.}{2.}
If a line is parallel to
a plane, then through any point in the plane
there is a line in the plane parallel to the given
line.
\end{Corollary}

\Indent\begin{Corollary}{92.}{3.}
The intersections of a plane
with two parallel planes are parallel lines.
\end{Corollary}
\end{minipage}
\hfill\smash{\Input{028c}{1.5in}}



\Section{PLANES PERPENDICULAR TO A LINE ARE PARALLEL}

\begin{Theorem}{93.}{IX.}
If each of two planes is perpendicular
to the same line, they are parallel; and

Conversely, if one of two parallel planes is perpendicular
to a line, the other is also.
\end{Theorem}
\begin{center}
\Input{029ab}{}
\end{center}

\Objective
{Given (1) plane $M\perp AB$ and plane $N\perp AB$. \textsc{Fig}.~1.}
{To prove that $M\parallel N$.}

\Proof: Suppose $M$ and $N$ to meet in some point $P$. Draw
$AP$ in $M$ and $BP$ in $N$. Then $AB\perp AP$ and $AB\perp BP$ (§~\Sref{71}),
which is impossible.\hfill §~\Sref{29}

\Objective
{Given (2) $M\parallel N$ and $M\parallel AB$. \textsc{Fig}.~2.}
{To prove that $N\parallel AB$.}

\Proof: Through $AB$ pass a plane cutting $M$ and $N$ in $AC$
and $BD$, and a second plane cutting $M$ and $N$ in $AE$ and $BF$.

Then, $AC\parallel BD$ and $AB\parallel BF$.\hfill §~\Sref{92}

Now prove (1) $AB\perp BD$, (2) $AB\perp BF$.\hfill §~\Sref{35}

\null\hfill $AB\perp N$.\hfill §~\Sref{76}

\begin{Corollary}{94.}{1.}
Parallel line-segments included between
parallel planes are equal.
\end{Corollary}

\begin{Corollary}{95.}{2.}
If a line is perpendicular to one of two
parallel planes, it is perpendicular to the other also.
\end{Corollary}

\begin{Corollary}{96.}{3.}
Two planes each parallel to a third plane
are parallel to each other.
\end{Corollary}


\Section{PARALLEL PLANES}

\begin{Theorem}{97.}{X.}
If a plane is parallel to each of
two intersecting lines, it is parallel to the plane of these
lines.
\end{Theorem}
\begin{center}
\Input{030a}{0.6\textwidth}
\end{center}

\Objective
{Given a plane $M$ parallel to the intersecting lines $l_1$ and $l_2$.}
{To prove that the plane $M$ is $\parallel$ the plane $N$ of $l_1$ and $l_2$.}

\Proof: If $M$ is not $\parallel N$, these planes meet in a line $l_3$.
\hfill §~\Sref{69}

Then neither $l_1$ nor $l_2$ can meet $l_3$, since they are $\parallel M$.

Hence $l_1\parallel l_3$, and $l_2\parallel l_3$, which is impossible.
\hfill §~\Sref{21}

$\therefore M$ and $N$ cannot meet and are parallel.
\QED

\begin{Theorem}{98.}{XI.}
Through a point not in a plane
there is one and only one plane parallel to this plane.
\end{Theorem}

\noindent\begin{minipage}[b]{\textwidth-1.75in}
\Objective{\Indent Given a plane $M$ and a point~$P$ not in~$M$.}
          {\Indent To prove that through~$P$ there is one and only
           one plane $\parallel M$.}
\end{minipage}
\hfill\smash{\raisebox{-0.125in}{\Input{030b}{1.75in}}}

\Proof: Let $l$ be a line through $P$ and $\perp M$.

Through $P$ draw $l_1$ and $l_2$ each $\perp l$.\hfill §~\Sref{75}

The plane $N$ of $l_1$ and $l_2$ is $\perp l$, and hence $N\parallel M$.
\hfill §§~\Sref{76}, \Sref{93}

If through $P$ there were another plane $R\parallel M$, then
$R$ would be $\perp l$ at~$P$.
\hfill §~\Sref{93}

But $N$ and $R$ cannot both be $\perp l$ at $P$.
\hfill §~\Sref{78}

Hence $N$ is the only plane through $P\parallel M$.
\QED 


\Section{PLANES PARALLEL TO GIVEN LINES}

\begin{Theorem}{99.}{XII.}
Through one of two skew lines
there is one and only one plane parallel to the other line.
\end{Theorem}
\begin{center}
\Input{031a}{0.6\textwidth}
\end{center}

\Objective
{Given two skew lines $l_1$ and $l_2$. See §~\Sref{7}.}
{To prove that through $l_1$ there is one and only one plane $\parallel l_2$.}

\Proof: Through $P$, a point in $l_1$, draw a line $l_3\parallel l_2$.

Then $l_1$ and $l_3$ determine a plane $M\parallel l_2$.\hfill  §~\Sref{90}

Any other plane $N$ through $l_1$ would meet the plane of $l_3$ and
$l_2$ in a line through $P$ not $\parallel l_2$ and hence $N$ would meet $l_2$. \QED 

\begin{Theorem}{100.}{XIII.}
Through a point outside of
each of two non-parallel lines there is one and only one
plane parallel to both of these lines.
\end{Theorem}
\begin{center}
\Input{031b}{0.6\textwidth}
\end{center}

\Objective
{Given a point $P$ outside of the non-parallel lines $l_1$ and $l_2$.}
{To prove that there is one and only one plane $M$ through $P$
parallel to $l_1$ and~$l_2$.}

\Proof: Through $P$ pass $l_3\parallel l_1$ and $l_4\parallel l_2$.

Then the plane $M$ of $l_3$ and $l_4$ is parallel to $l_1$ and $l_2$.
\hfill §~\Sref{90}

In any other plane $N$ through $P\parallel l_1$ and $l_2$, there are lines
$l'_3$ and $l'_4$ through $P$ such that $l'_3\parallel l_1$ and $l'_4\parallel l_2$.
\hfill §~\Sref{91}

In that case $l'_3$ is identical with $l_3$ and $l'_4$ with $l_4$.
\hfill §~\Sref{21}

Hence any such plane $N$ is identical with $M$.
\QED


