\Section{ANGLES WHOSE SIDES ARE PARALLEL}

\begin{Theorem}{101.}{XIV.} If two intersecting lines in
one plane are parallel, respectively, to two intersecting
lines in another plane, then the two planes are parallel,
and the corresponding angles formed by the lines are
equal.
\end{Theorem}

\begin{center}
\Input{033a}{0.6\textwidth}
\end{center}

\Objective
{Given the planes $M$ and $N$ in which $AB\parallel A'B'$, and $AC\parallel A'C'$.}
{To prove that $M\parallel N$ and $\angle 1 = \angle 2$.}

\Proof: (1) If $M$ is not $\parallel N$, then these planes meet in a
line $l$.
\hfill Why?

Then neither $AB$ nor $AC$ can meet $l$ since each is $\parallel N$.

$\therefore AB\parallel l$ and $AC\parallel l$ which is impossible.
\hfill Why?

(2) To prove $\angle 1 = \angle 2$, lay off $AB = A'B'$, $AC = A'C'$, and
draw $BC$, $B'C'$, $AA'$, $BB'$, and $CC'$.

\textit{Analysis}: $\angle 1 = \angle 2$ if $\triangle ABC = \triangle A'B'C'$, which is true
if $BC = B'C'$.

But $BC=B'C'$ if $BB'C'C$ is a $\Pgram$, which is so if $BB' = CC'$
and $BB' \parallel CC'$. This last is true if $AA'C'C$ and $AA'B'B$ are
$\Pgrams$, for then $BB' = AA' = CC'$ and $BB'\parallel AA'\parallel CC'$.

Hence we need to prove in order (1) $AA'C'C$ and $AA'B'B$
are $\Pgrams$, (2) $BB'C'C$ is a $\Pgram$, (3) $\triangle ABC=\triangle A'B'C'$, and
(4) $\angle BAC = \angle B'A'C'$.

Hence it is proved that the planes are parallel and the angles
are equal.
\QED

\begin{Corollary}{102.}{}
Two angles in space whose sides are
parallel each to each are either equal or supplementary.
\end{Corollary}



\Section{PARALLEL PLANES INTERCEPT PROPORTIONAL SEGMENTS}

\begin{Theorem}{103.}{XV.}
If two straight lines are cut
by three parallel planes, the intercepted segments on
one line are proportional to the corresponding segments
on the other.
\end{Theorem}
\begin{center}
\Input{034a}{0.4\textwidth}
\end{center}

\Objective
{Given the lines $AB$ and $CD$ cut by the planes $M$, $N$, and~$P$.}
{To prove that $\dfrac{AE}{EB} = \dfrac{CG}{GD}$.}

\textbf{Outline of Proof}: Draw $AD$ and let the plane determined by
$AD$ and $CD$ cut the planes $M$ and $N$ in $AC$ and $FG$ respectively;
and let the plane of $AB$ and $AD$ cut $N$ and $P$ in $EF$
and $BD$ respectively.

Then prove (1) $FG\parallel AC$ and $EF\parallel BD$,
\[
(2)\quad \dfrac{AE}{EB} = \dfrac{AF}{FD} \text{ and }
         \dfrac{CG}{GD} = \dfrac{AF}{FD},\qquad
(3)\quad \dfrac{AE}{EB} = \dfrac{CG}{GD}.
\]

\begin{Corollary}{104.}{} Parallel planes which intercept equal segments
on any transversal line intercept equal segments on every
transversal line.
\end{Corollary}

