\Section{DIHEDRAL ANGLES}
\SecToc{Dihedral Angles}

\Paragraph{105.}{Dihedral Angle.} The part of a plane on one side of a
\index{Angle@\textbf{Angle}!dihedral}
\index{Dihedral@\textbf{Dihedral angles}}
\index{Edge@\textbf{Edge}!of a dihedral angle}
\index{Faces@\textbf{Faces}!of a dihedral angle}
\index{Halfplane@\textbf{Half-plane}}
line in it is called a \emph{half-plane}. The line is called the \emph{edge} of
the half-plane. Two half-planes meeting in a common edge
form a \emph{dihedral angle}. The common edge is the \emph{edge} of the
angle and the half-planes are its \emph{faces}.

\Paragraph{106.}{Plane Angle of a Dihedral Angle.} Two lines in the respective
\index{Dihedral@\textbf{Dihedral angles}!plane angle of of}
\index{Plane Angle@\textbf{Plane Angle}!of a dihedral angle}
faces of a dihedral angle and perpendicular to its
edge at a common point form a plane angle, which
is called \emph{the plane angle of the dihedral angle}.

\noindent\begin{minipage}[b]{\textwidth-1.25in}
\Indent\begin{Remark}
In the figure, the half-planes $M$ and $N$ form the dihedral
angle $M$-$AB$-$N$, read by naming the two faces and the
edge. If $CD$ in $N$ is $\perp AB$ and $ED$ in $M$ is $\perp AB$, then
$\angle CDE$ is the plane angle of the dihedral angle $M$-$AB$-$N$.
\end{Remark}


By §~\Sref{101} all plane angles of a dihedral angle
are equal to each other.

\Indent\Paragraph{107.}{Generation of a Dihedral Angle.} A dihedral
\index{Dihedral@\textbf{Dihedral angles}!generation of}
angle may be thought of as \emph{generated} by the
rotation of a half-plane about its edge. The
magnitude of the angle depends solely upon the
\emph{amount of rotation}.
\end{minipage}
\hfill\smash{\raisebox{-0.125in}{\Input{036ab}{1in}}}

\Paragraph{108.}{Equal Dihedral Angles.} Two dihedral angles are \emph{equal}
\index{Dihedral@\textbf{Dihedral angles}!equal}
when they can be so placed that they coincide.

\noindent\begin{minipage}[b]{\textwidth-2in}
\Indent\Paragraph{109.}{Right Dihedral Angle.} A right
\index{Dihedral@\textbf{Dihedral angles}!right}
dihedral angle is one whose \emph{plane angle}
is a right angle.

\Indent\Paragraph{110.}{Perpendicular Planes.} Two
planes are said to be \emph{mutually perpendicular}
if their dihedral angle is a right angle.
\index{Perpendicular@\textbf{Perpendicular}!plane to a plane}
\end{minipage}
\hfill\smash[t]{\raisebox{0.25in}{\Input{036c}{2in}}}

\begin{Remark}
Dihedral angles are \emph{acute} or \emph{obtuse} according as their plane angles
are acute or obtuse.

Two dihedral angles are \emph{adjacent}, \emph{vertical}, \emph{supplementary}, or \emph{complementary}
according as their plane angles possess these properties.
\end{Remark}


\Section{DIHEDRAL ANGLES AND THEIR PLANE ANGLES}

\begin{Theorem}{111.}{XVI.}
Two dihedral angles are
equal if their plane angles are equal; and

Conversely, if two dihedral angles are equal, their
plane angles are equal.
\end{Theorem}

\begin{center}
\Input{037ab}{0.6\textwidth}
\end{center}

\Objective{Given (1) the dihedral angles $M-AB-N$ and $M'-A'B'-N'$ in
which the plane $\Angles CDE$ and $C'D'E'$ are equal.}
{To prove that $\angle M-AB-N = \angle M'-A'B'-N'$.}

\Proof: Place the equal $\Angles CDE$ and $C'D'E'$ in coincidence.

Then $AB$ coincides with $A'B'$ since these lines are perpendicular
to the plane $CDE$ at the point~$D$.\hfill              §~\Sref{80}

Then $M$ and $M'$ coincide as do also $N$ and $N'$ since they are
determined by coincident lines.\hfill                 §~\Sref{73}
\[
\therefore\ \angle M-AB-N = \angle M'-A'B'-N'. \tag*{§~\Sref{108}}
\]

\Objective{Given (2) $\angle M-AB-N = \angle M'-A'B'-N'$.}
{To prove that the plane $\Angles CDE$ and $C'D'E'$ are equal.}

\Proof: Place the equal dihedral $\Angles M-AB-N$ and $M'-A'B'-N$
in coincidence so that the points $D$ and $D'$ coincide.

Then $CD$ and $C'D'$ coincide as do also $ED$ and $E'D'$.
\hfill §~\Sref{29}
\[
\therefore\ \angle CDE = \angle C'D'E'. \tag*{\QED}
\]

\begin{Corollary}{112.}{}
All right dihedral angles are equal.
\end{Corollary}

\Paragraph{113.}{Measure of a Dihedral Angle.} It follows from §~\Sref{111}
\index{Dihedral@\textbf{Dihedral angles}!measure of}
that the plane angle of a dihedral angle may be regarded as
its measure.


\Section{MUTUALLY PERPENDICULAR PLANES}

\begin{Theorem}{114.}{XVII.}
If two planes are mutually
perpendicular, and if a line is drawn from a point in
one perpendicular to their intersection, then this line
is perpendicular to the second plane.
\end{Theorem}

\begin{center}
\Input{038a}{0.4\textwidth}
\end{center}

\Objective
{Given plane $M \perp$ plane $N$ and a point $P$ in~$M$. Let $l_1$ be the
intersection of $M$ and $N$ and $l$ a line in $M$ through $P\perp l_1$.}
{To prove that $l\perp N$.}

\Proof: Let $l$ meet $l_1$ in $O$. Through $O$ draw $l_2$ in $N$ and
perpendicular to $l_1$.

Then the angle formed by the lines $l$ and $l_2$ is the plane angle
of the dihedral angle between the planes $M$ and $N$.
\hfill §~\Sref{106}
\begin{align*}
\therefore\quad l &\perp l_2  \tag*{§~\Sref{109}} \\
\therefore\quad l &\perp N.   \tag*{Why?}  \\
\tag*{\QED}
\end{align*}

\begin{Corollary}{115.}{}
If two planes are mutually perpendicular
and if a line is drawn from a point in one and perpendicular to
the other, then this line lies in the first plane and is perpendicular
to the intersection of the two planes.
\end{Corollary}

\Proof: By the theorem there is a line through $P$ which lies
in the plane $M$ and is $\perp N$. But through $P$ there is only one
line $\perp N$.\hfill    §~\Sref{80}


\Section{PLANE PERPENDICULAR TO EACH OF TWO PLANES}

\begin{Theorem}{116.}{XVIII.}
If a plane is perpendicular
to each of two planes, it is perpendicular to their line
of intersection.
\end{Theorem}

\begin{center}
\Input{039a}{0.6\textwidth}
\end{center}

\Objective{Given $Q\perp M$ and $Q\perp N$ and $l$ the intersection of $M$ and~$N$.}
{To prove that $Q\perp l$.}

\Proof: From a point $P$ common to $M$ and $N$ draw a line
$l'\perp Q$.

Then $l'$ lies in both $M$ and $N$.\hfill §~\Sref{115}

Hence, $l'$ and $l$ are the same line.\hfill Why?

That is, $l\perp Q$, or $Q\perp l$. \QED


