\Section{PERPENDICULAR  LINES  AND  PLANES}

\begin{Theorem}{117.}{XIX.}
If a line is perpendicular to
a plane, every plane containing this line is perpendicular
to that plane.
\end{Theorem}

\begin{center}
\Input{040a}{0.4\textwidth}
\end{center}

\Objective{Given a line $l\perp$ plane $N$ at $P$.}
{To prove that a plane $M$ containing $l$ is $\perp N$.}

\Proof: Let $l_1$ be the intersection of $M$ and $N$. In $N$ draw
$l_2\perp l_1$ at $P$.

Then\hfill $l\perp l_1$, $l_2\perp l_1$, and $l\perp l_2$.\hfill Why? \\
\null\hfill $\therefore\ M\perp N$.\hfill Why? \\
\QED

\begin{wrapfigure}[5]{r}{1.5in}
\Input{040b}{1.5in}
\end{wrapfigure}
\Paragraph{118.}{Projection of a Figure on a Plane.} The projection of a
\index{Foot@\textbf{Foot}!of a perpendicular}
\index{Plane@\textbf{Plane}!projections upon}
\index{Projection@\textbf{Projection}!of a figure}
point on a plane is the foot of the perpendicular from the
point to the plane. The projection  of
any \emph{figure} on a plane is the locus of the
projections of all points of the figure on
the plane.

\begin{Remark}
Thus, $B$ is the projection of the point $A$ on $M$,
and $l_2$ is the projection of the line $l_1$ on $M$.
\end{Remark}

\Paragraph{119.}{Angle Between Line and Plane.} The angle between a
\index{Angle@\textbf{Angle}!between a line and a plane}
\index{Angle@\textbf{Angle}!of projection}
\index{Projection angle@\textbf{Projection angle}}
plane and a line oblique to it is understood to be the \emph{acute
angle} formed by the line and its projection upon the plane.

\Paragraph{120.}{Bisector of a Dihedral Angle.} A half-plane bisects a
\index{Dihedral@\textbf{Dihedral angles}!bisector of}
dihedral angle if it passes through the edge of the dihedral
angle and bisects its plane angle.


\Section{PROJECTION  OF  A  STRAIGHT  LINE ON  A  PLANE}

\begin{Theorem}{121.}{XX.}
\index{Projection@\textbf{Projection}!of a line-segment}
The projection of a straight
line on a plane is a straight line in that plane.
\end{Theorem}

\begin{center}
\Input{041a}{0.4\textwidth}
\end{center}

\Objective{Given a plane $M$ and a line $AB$ projected upon it.}
{To prove that the projection is a straight line.}

\Proof: Project any three points $A$, $E$, $B$ of the line $AB$
into the points $C$, $F$, $D$ in the plane $M$.

Then $AC$ and $BD$ determine a plane $\perp M$.\hfill §§~\Sref{83}, \Sref{117}

Hence, by §§~\Sref{115}, \Sref{69}, any three points, $C$, $F$, $D$, of the projection
lie in a straight line, that is, the projection is a straight
line.
\QED 

\begin{Theorem}{122.}{XXI.}
The acute angle formed by a
straight line with its own projection on a plane is the
least angle which it makes with any line in that plane.
\end{Theorem}

\begin{center}
\Input{041b}{0.4\textwidth}
\end{center}

\Objective{Given $CB$ the projection of $AB$ on the plane $M$, and any other
line $BD$ in $M$ through $B$.}
{To prove that $\angle ABD > \angle ABC$.}

\Proof: Draw $AC\perp M$, make $BD = BC$, and draw $AD$.
Then prove $AD > AC$ and $\therefore \angle ABD > \angle ABC$.\hfill §~\Sref{33}


\Section{PLANE BISECTING A DIHEDRAL ANGLE}

\begin{Theorem}{123.}{XXII.}
The locus of all points equally
distant from the faces of a dihedral angle is the half-plane
bisecting the angle.
\end{Theorem}

\begin{center}
\Input{042ab}{}
\end{center}

\Objective{Given the half-plane $P$ bisecting the dihedral $\angle M-AB-N$.}
{To prove {\upshape(1)} that any point $E$ in $P$ is equally distant from $M$
and~$N$, and {\upshape(2)} that any point which is equally distant from $M$
and $N$ lies in~$P$.}

\Proof: (1) Draw $EC\perp M$ and $ED\perp N$.

Then (a) Plane $CED\perp M$ and also $\perp N$.\hfill Why?

$\phantom{\text{Then}}$ (b) Plane $CED\perp AB$.\hfill Why?

Now $\angle COE$ is the plane $\angle$ of $M-AB-P$, \\
and $\angle DOE$ is the plane $\angle$ of $N-AB-P$.\hfill Why? \\
\null\hfill $\therefore \angle COE = \angle DOE$ by the hypothesis.\hfill \\
Hence\hfill $EC = ED$.\hfill §§~\Sref{42}, \Sref{23}

(2) Let $E$ be any point such that $EC = ED$, these being
perpendicular respectively to $M$ and $N$.

Then $\angle COE = \angle DOE$.\hfill §§~\Sref{40}, \Sref{23}

Hence, the plane $P$ determined by $ABE$ is the bisector of
the given dihedral angle, that is, the point $E$ lies in $P$.
\QED

