\Section{TRIANGLES POLAR TO EACH OTHER}

\begin{Theorem}{337.}{XIV.}
If $A'B'C'$ is the polar triangle
of $ABC$, then $ABC$ is the polar triangle of
$A'B'C'$.
\end{Theorem}

\vspace*{-0.125in}
\begin{center}
\Input{135ab}{}
\end{center}
\vspace*{-0.25in}

\Objective{Given $\triangle A'B'C'$, the polar triangle of $ABC$.}
{To prove that $ABC$ is the polar triangle of $A'B'C'$.}

\Proof: (1)~$A'$ is at a quadrant's distance from $B$ because $B$ is
the pole of $\wideparen{A'C'}$. $A'$ is also at a quadrant's distance from~$C$
because $C$ is the pole of $\wideparen{A'B'}$.

Hence, $A'$ is the pole of $\wideparen{BC}$.\hfill §~\Sref{300}

Similarly, $B'$ is the pole of $\wideparen{AC}$ and $C'$ the pole of $\wideparen{AB}$.

(2)~To show that $A$ and~$A'$ lie on the same side of the circle
$BC$, we note that since $A$ is the pole of the circle $B'C'$ and
$A$ lies on the same side of this circle with $A'$, then $A$ and~$A'$
are at less than a quadrant's distance. Hence, it follows that
if $A'$ is at a quadrant's distance from $BC$, $A$ and~$A'$ must be
on the same side of~$BC$.

In like manner we show that $B$ and~$B'$ lie on the same side
of $AC$, and $C$ and~$C'$ on the same side of~$AB$.

\Paragraph{338.}{Corresponding Parts of Polar Triangles.} If $ABC$ and
\index{Corresponding@\textbf{Corresponding}!parts of polar triangles}
\index{Polar@\textbf{Polar}!triangles}
$A'B'C'$ are polar triangles, and if $A$ is a pole of $\wideparen{B'C'}$, then
$\angle A$ and $\wideparen{B'C'}$ are said to be \emph{corresponding parts}.


\Section{MEASURE OF PARTS IN POLAR TRIANGLES}

\begin{Theorem}{339.}{XV.}
The sum of the measures of
an angle of a spherical triangle and the corresponding
arc of its polar triangle is~$180$°.
\end{Theorem}

\textbf{Given the polar triangles $ABC$ and $A'B'C'$. Denote the measures
in degrees of the angles by $A$, $B$, $C$, $A'$, $B'$, $C'$, and of the
corresponding sides by $a'$, $b'$, $c'$, $a$, $b$, $c$}.

\vspace*{-0.125in}
\begin{center}
\Input{136a}{}
\end{center}
\vspace*{-0.25in}

\begin{flalign*}
&\text{\itshape To prove that} &
  A + a' &= 180\text{°}\qquad   A' + a = 180\text{°} && \\
&&B + b' &= 180\text{°}\qquad   B' + b = 180\text{°} && \\
&&C + c' &= 180\text{°}\qquad   C' + c = 180\text{°} &&
\end{flalign*}

\textbf{Suggestions for Proof}: Extend (if necessary) arcs $A'B'$ and
$A'C'$ till they meet the great circle $BC$ in points $D$ and $E$,
respectively. Then arc $DE$ is the measure of $\angle A'$.

Also $\wideparen{BE} = 90$°, and $\wideparen{DC} = 90$°. (Why?)

But $\wideparen{BE} + \wideparen{DC} = \wideparen{BC} + \wideparen{ED} = a + A' = 180$°.

\begin{Corollary}{340.}{1.}
If in two spherical triangles an angle of
one is equal to an angle of the other, then the corresponding sides
of their polar triangles are equal; and conversely, if in two
spherical triangles a side of one is equal to a side of the other,
then the corresponding angles of their polar triangles are equal.
\end{Corollary}

\begin{Corollary}{341.}{2.}
If two spherical triangles are equal or
symmetrical, their polar triangles are equal or symmetrical.
\end{Corollary}


\Section{SUM OF ANGLES OF A SPHERICAL TRIANGLE}

\begin{Theorem}{342.}{XVI.}
The sum of the angles of a
spherical triangle is less than six right angles and
greater than two right angles.
\end{Theorem}

\begin{center}
\Input{137ab}{}
\end{center}

\Objective{Given the spherical triangle $ABC$.}
{To prove that \Inum{(1)}~$\angle A + \angle B + \angle C < 6$ rt.\ angles.\\
\indent\phantom{To prove that }\Inum{(2)}~$\angle A + \angle B + \angle C > 2$ rt.\ angles.}

\Proof: Construct the polar triangle $A'B'C'$, with sides
$a'$, $b'$, $c'$.

(1)~By §~\Sref{339} $\angle A + \angle B + \angle C + a' + b' + c' = 6 \text{ rt.\ } \Angles$.

Since $a' + b' + c' > 0$, $\therefore\quad \angle A + \angle B + \angle C < 6 \text{ rt.\ } \Angles$.

(2)~Using §~\Sref{322}, show that $\angle A + \angle B + \angle C > 2 \text{ rt.\ } \Angles$.

\begin{Corollary}{343.}{1.}
State and prove the theorem on trihedral
angles which corresponds to Theorem~XVI.
\end{Corollary}

\begin{Corollary}{344.}{2.}
The sum of the angles of a spherical
polygon of $n$~sides is greater than $2(n - 2)$ right angles and less
than $2n$ right angles.
\end{Corollary}

\Proof: Divide the polygon into $n - 2$ triangles. Then by
§~\Sref{342} the sum of the angles $> 2(n - 2) \text{ rt.\ } \Angles$.

Since each angle is less than two right angles, it follows
that the sum is less than $2n$ right angles.

\begin{Corollary}{345.}{3.}
State and prove the theorem on polyhedral
angles which corresponds to Corollary~2.
\end{Corollary}


