\Section{AREA OF A ZONE. VOLUME OF A SPHERICAL CONE}

\Paragraph{374.}{Area of a Zone.} An argument precisely like that of
\index{Area@\textbf{Area}!of a zone}
\index{Measurement@\textbf{Measurement}!of surfaces}
§~\Sref{368} shows that the area of a zone is
\[
s = 2\pi rh,
\]
where $h$ is the altitude of the zone.

That is, instead of $AB$, the diameter in case of the sphere,
we should have the sum of the altitudes of the frustums circumscribed
about the zone equal to~$h$, the altitude of the zone.

\Paragraph{375.}{Volume of a Spherical Cone and a Spherical Sector.} An
\index{Volume@\textbf{Volume}!of a spherical cone}
\index{Volume@\textbf{Volume}!of a spherical sector}
\index{Measurement@\textbf{Measurement}!of volumes}
argument precisely like that of §~\Sref{371} shows that the volume
of a spherical cone is
\[
v = \dfrac{r}{3} \cdot s,
\]
where $s$ is the area of the zone of one base which is cut out of
the sphere by the cone. Hence, if $h$ is the altitude of this
zone, we have
\[
v = \dfrac{r}{3} \cdot 2\pi rh = \dfrac{2\pi}{3} r^2h.
\]

In like manner the \emph{volume of a spherical sector} is
\[
v = \dfrac{2\pi}{3} r^2h,
\]
where $h$ is the altitude of the zone of two bases which is cut
out by the sector.


\begin{Exercises}

\item[1.] The radius of a sphere is $6$~in.\ and the altitude of a zone
is $5$~in. Find the area of the sphere and of the zone.

\item[2.] The area of a zone is $36\pi$~sq.~ft.\ and its altitude $4$~ft.
Find the radius of the sphere.

\item[3.] On a sphere of radius $8$~in.\ a spherical cone cuts out a
zone whose altitude is $2$~in. Find the volume of the cone.

\item[4.] Find the volume of the spherical sector cut out of a
sphere of radius $9$~in., if the altitude of the zone is $2$~in.
\end{Exercises}


\Section{VOLUME OF A SPHERICAL SEGMENT}

\noindent\begin{minipage}[b]{\textwidth-1.5in}
\Indent\begin{Problem}{376.}
\index{Volume@\textbf{Volume}!of a spherical segment}
To find the volume of a spherical
segment.
\end{Problem}

\Indent\textbf{Solution}. Let $r$ be the radius of the
sphere, and $r_1$ and $r_2$ the radii of the
bases of the segment, $h$ the altitude of
the segment, and let the segment be generated
by revolving the figure $ACDB$ about
$AO$ as an axis.
\end{minipage}
\hfil\Input{156a}{1.5in}\hfil

\begin{flalign*}
&\indent\text{We have Vol.\ generated by } & ODB &= \dfrac{2\pi}{3} r^2h. && && \tag*{§~\Sref{375}} \\
&\indent\text{\phantom{We have }Vol.\ generated by\ } & OAB &= \dfrac{\pi}{3} r_1^2(h+d). && && \tag*{(Why?)} \\
&\indent\text{\phantom{We have }Vol.\ generated by\ } & OCD &= \dfrac{\pi}{3} r_2^2d. && && \tag*{(Why?)} \\
\end{flalign*}
\begin{flalign*}
&\indent\text{Hence,} & v &= \dfrac{2\pi}{3} r^2h + \dfrac{\pi}{3} r_1^2(h+d) - \dfrac{\pi}{3} r_2^2d && \\
&&                        &= \dfrac{\pi}{3} \bigl[2r^2h + r_1^2h + d(r_1^2 - r_2^2)\bigr]. && \tag*{(1)} \\
&\indent\text{From} & r^2 &= r_2^2 + d^2 \text{ and } r^2 = r_1^2 + (h+d)^2 && \\
&\text{we obtain} & d &= \dfrac{r_2^2 - r_1^2 - h^2}{2h}. && \tag*{(2)}
\end{flalign*}

Substituting this value of $d$ in $r^2 = r_2^2 + d^2$, \\
we get\hfill $r^2 = \dfrac{r_2^4 + r_1^4 + h^4 - 2r_1^2r_2^2 + 2h^2r_2^2 + 2h^2r_1^2}{4h^2}$.\hfill (3)

Substituting (2) and~(3) in~(1) and reducing, we have
\[
v = \dfrac{\pi h}{2} (r_1^2 + r_2^2) + \dfrac{\pi}{6} h^3. \tag*{\QEF}
\]

\begin{Corollary}{377.}{}
The volume of a spherical segment of one
base is
\[
v = \pi h^2 \left( r - \dfrac{h}{3} \right).
\]
\end{Corollary}

\begin{Suggestion}
In this case $r_1^2 = 0$ and $r_2^2 = r^2 - (r - h)^2 = 2rh - h^2$.
Substituting in the formula above, we have the result.
\end{Suggestion}


