\Section{FORMULAS DEVELOPED IN BOOKS III, IV, V}

\begin{Itemize}

\item[1.] If $V$ is the volume of a rectangular parallelopiped
whose dimensions are $a$, $b$, $c$, then
\[
V = abc.
\]

\item[2.] If $V$ is the volume, $b$ the area of the base, and $h$ the
altitude of a prism or cylinder, then
\[
V = hb.
\]

\item[3.] If $S$ is the lateral surface, $p$ the perimeter of a right
section of a prism or cylinder, and $e$ the lateral edge or element,
then
\[
S = pe.
\]

\item[4.] If $V$ is the volume, $b$ the area of base, and $h$ the altitude
of a pyramid or cone, then
\[
V = \tfrac{1}{3} bh.
\]

\item[5.] If $S$ is the lateral area, $p$ the perimeter of the base, and
$l$ the slant height of a regular pyramid or cone, then
\[
S = \tfrac{1}{2} pl.
\]

\item[6.] If $V$ is the volume, $b$ the lower base, $b'$ the upper base,
and $h$ the altitude of a frustum of pyramid or cone, then
\[
V = \tfrac{1}{3} h (b + b' + \sqrt{bb'}).
\]

\item[7.] If $S$ is the area of the surface, $V$ the volume, and $r$ the
radius of a sphere, then
\[
S = 4 \pi r^2 \text{ and } V = \tfrac{4}{3} \pi r^3.
\]

\item[8.] If $a$ is the spherical excess in degrees of a spherical
polygon, $S$ the area in square units, and $r$ the radius of a
sphere, then
\[
S = \dfrac{a}{720} \cdot 4 \pi r^2.
\]

\item[9.] If $S$ is the area, $h$ the altitude, and $r$ the radius of a lune,
then
\[
S = 2 \pi rh.
\]


\item[10.] If $V$ is the volume of spherical cone, $h$ the altitude,
and $r$ the radius of the sphere, then
\[
V = \dfrac{2\pi}{3}r^2h.
\]

\item[11.] If $V$ is the volume of a spherical segment, $r$ the radius
of the sphere, $r_1$ and $r_2$ the radii of the bases, and $h$ the altitude
of the segment, then
\[
V = \dfrac{\pi h}{2}(r_1^2 + r_2^2) + \dfrac{\pi}{6} h^3.
\]
\end{Itemize}


